// Generated by scripts/sync-content.mjs from ROADMAP.md, CHANGELOG.md and git.
import raw from '@/.generated/site-data.json';

export type Status = 'done' | 'progress' | 'open';
export interface Counts {
  done: number;
  progress: number;
  open: number;
  total: number;
}
export interface RoadmapItem {
  status: Status;
  name: string;
  detail: string;
}
export interface Milestone {
  title: string;
  items: RoadmapItem[];
  counts: Counts;
}
export interface Release {
  title: string;
  entries: { category: string; text: string }[];
}
export interface SiteData {
  roadmap: { milestones: Milestone[]; totals: Counts };
  changelog: Release[];
  credits: { budgetUsd: number; spentUsd: number; leftUsd: number; updatedAt: string } | null;
  build: { builtAt: string; sha: string; branch: string; commitDate: string; dirty: boolean };
}

export const siteData = raw as SiteData;
